style.css:
@-moz-document domain("stoxosnet.gr") {
:root {
  --pink-bg: #fff7fa;
  --pink-light: #f7e4ea;
  --pink-soft: #ebc5d2;
  --pink-main: #d9a5b8;
  --pink-dark: #bd829b;
  --pink-deep: #95647b;
  --pink-text: #795363;
  --pink-white: #fffdfd;
  --pink-border: #f0d6df;
}

/* Main background */

html, body {
  background: var(--pink-bg) !important;
  color: var(--pink-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* Headings */

h1, h2, h3, h4, h5 {
  color: var(--pink-deep) !important;
  font-family: Georgia, serif !important;
  font-weight: 600 !important;
}

/* Links */

a {
  color: var(--pink-dark) !important;
  text-decoration: none !important;
  transition: color .2s ease;
}

a:hover {
  color: var(--pink-deep) !important;
}

/* Navigation */

.navbar,
.navbar-default,
.navbar-inverse {
  background: var(--pink-white) !important;
  border: 1px solid var(--pink-border) !important;
  border-radius: 14px !important;
  box-shadow: 0 4px 15px #d9a5b81c !important;
}

.navbar a {
  color: var(--pink-text) !important;
}

.navbar a:hover {
  background: var(--pink-light) !important;
  border-radius: 10px !important;
}

/* Cards and panels */

.panel,
.card,
.well,
.modal-content,
.dropdown-menu {
  background: var(--pink-white) !important;
  border: 1px solid var(--pink-border) !important;
  border-radius: 15px !important;
  box-shadow: 0 5px 18px #bd829b18 !important;
  color: var(--pink-text) !important;
}

.panel-heading,
.card-header {
  background: var(--pink-light) !important;
  color: var(--pink-deep) !important;
  border-color: var(--pink-border) !important;
  border-radius: 14px 14px 0 0 !important;
}

/* Buttons */

button,
.btn,
input[type="submit"],
input[type="button"] {
  background: var(--pink-main) !important;
  color: white !important;
  border: 1px solid var(--pink-main) !important;
  border-radius: 10px !important;
  padding: 8px 17px !important;
  font-weight: 600 !important;
  transition: all .2s ease !important;
}

button:hover,
.btn:hover,
input[type="submit"]:hover,
input[type="button"]:hover {
  background: var(--pink-dark) !important;
  border-color: var(--pink-dark) !important;
  box-shadow: 0 4px 12px #bd829b40 !important;
  transform: translateY(-1px);
}

/* Form fields */

input:not([type="checkbox"]):not([type="radio"]),
select,
textarea,
.form-control {
  background: #fffafb !important;
  color: var(--pink-text) !important;
  border: 1px solid var(--pink-border) !important;
  border-radius: 10px !important;
  box-shadow: none !important;
}

input:focus,
select:focus,
textarea:focus,
.form-control:focus {
  border-color: var(--pink-main) !important;
  outline: none !important;
  box-shadow: 0 0 0 3px #d9a5b833 !important;
}

/* Tables */

table {
  background: var(--pink-white) !important;
  border-radius: 12px !important;
  overflow: hidden;
  color: var(--pink-text) !important;
}

th {
  background: var(--pink-light) !important;
  color: var(--pink-deep) !important;
}

td {
  border-color: var(--pink-border) !important;
}

tr:hover td {
  background: #fff2f6 !important;
}

/* Labels and alerts */

.label,
.badge {
  background: var(--pink-soft) !important;
  color: var(--pink-deep) !important;
  border-radius: 20px !important;
}

.alert,
.alert-info,
.alert-success,
.alert-warning {
  background: #fff0f5 !important;
  border: 1px solid var(--pink-border) !important;
  border-radius: 12px !important;
  color: var(--pink-text) !important;
}

/* Checkboxes */

input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--pink-dark) !important;
}

/* Selection */

::selection {
  background: var(--pink-soft);
  color: var(--pink-deep);
}

/* Scrollbar */

::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

::-webkit-scrollbar-track {
  background: var(--pink-bg);
}

::-webkit-scrollbar-thumb {
  background: var(--pink-soft);
  border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--pink-dark);
}
}

@-moz-document domain("stoxosnet.gr") {
:root {
  --bg: #fff6f9;
  --white: #fffdfd;
  --blush: #f9e8ee;
  --pink: #e9c2d0;
  --rose: #d49aaf;
  --dusty: #bd8199;
  --deep: #98647c;
  --text: #765363;
  --border: #efd5df;
}

/* ===== GENERAL ===== */

html, body {
  background: var(--bg) !important;
  color: var(--text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

body {
  background-image:
    radial-gradient(circle at 10% 15%, #f5dce680, transparent 30%),
    radial-gradient(circle at 90% 80%, #f5dce650, transparent 35%) !important;
}

/* ===== TOP HEADER ===== */

header, .header {
  background: var(--white) !important;
  border-color: var(--border) !important;
}

/* ===== NAVIGATION ===== */

.navbar,
.navbar-default,
.navbar-inverse {
  background: var(--white) !important;
  border: 1px solid var(--border) !important;
  border-radius: 17px !important;
  box-shadow: 0 5px 18px #bd81991c !important;
}

.navbar-nav > li > a,
.navbar a {
  color: var(--deep) !important;
  font-weight: 600 !important;
  transition: .2s ease !important;
}

.navbar-nav > li > a {
  background: var(--pink) !important;
  border-radius: 12px !important;
  margin: 3px 2px !important;
}

.navbar-nav > li > a:hover,
.navbar-nav > .open > a {
  background: var(--dusty) !important;
  color: white !important;
}

/* Dropdown menus */

.dropdown-menu {
  background: var(--white) !important;
  border: 1px solid var(--border) !important;
  border-radius: 12px !important;
  box-shadow: 0 6px 18px #bd819933 !important;
}

.dropdown-menu > li > a {
  color: var(--deep) !important;
}

.dropdown-menu > li > a:hover {
  background: var(--blush) !important;
}

/* ===== LOGO ===== */

/* Recolour existing logo image */

img[src*="logo"],
.navbar-brand img,
header img {
  filter: grayscale(1) sepia(.25)
          saturate(1.5) hue-rotate(285deg)
          brightness(.95) !important;
}

/* ===== PAGE HEADINGS ===== */

h1, h2, h3, h4 {
  color: var(--deep) !important;
  font-family: Georgia, serif !important;
  font-weight: bold !important;
}

h2 {
  border-bottom: 2px solid var(--border) !important;
  padding-bottom: 10px !important;
}

/* ===== TIMETABLE ===== */

/* Main lesson cards */

.panel,
.panel-default,
.well,
.card {
  background: var(--white) !important;
  border: 1px solid var(--border) !important;
  border-radius: 13px !important;
  box-shadow: 0 4px 12px #bd81991c !important;
  overflow: hidden !important;
}

/* Weekday headers */

.panel-default > .panel-heading,
.panel-heading,
h3.panel-title {
  background: var(--dusty) !important;
  color: white !important;
  border-color: var(--dusty) !important;
  border-radius: 0 !important;
  font-weight: bold !important;
  padding: 12px 14px !important;
}

/* Lesson information */

.panel-body,
.panel-footer {
  background: var(--white) !important;
  color: var(--text) !important;
  border-color: var(--border) !important;
}

/* Lesson rows */

.list-group-item {
  background: var(--white) !important;
  color: var(--text) !important;
  border-color: var(--border) !important;
}

.list-group-item:hover {
  background: var(--blush) !important;
}

/* Timetable text */

td, th {
  border-color: var(--border) !important;
}

th {
  background: var(--blush) !important;
  color: var(--deep) !important;
}

td {
  color: var(--text) !important;
}

/* ===== LINKS ===== */

a {
  color: var(--dusty) !important;
  transition: .2s ease;
}

a:hover {
  color: var(--deep) !important;
}

/* ===== BUTTONS ===== */

button,
.btn,
input[type="submit"],
input[type="button"] {
  background: var(--dusty) !important;
  color: white !important;
  border: 1px solid var(--dusty) !important;
  border-radius: 10px !important;
  font-weight: bold !important;
  transition: .2s ease !important;
}

button:hover,
.btn:hover,
input[type="submit"]:hover {
  background: var(--deep) !important;
  transform: translateY(-1px);
}

/* ===== FORMS ===== */

input:not([type="checkbox"]):not([type="radio"]),
select,
textarea,
.form-control {
  background: #fffafb !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
  border-radius: 9px !important;
  box-shadow: none !important;
}

input:focus,
select:focus,
textarea:focus {
  border-color: var(--rose) !important;
  box-shadow: 0 0 0 3px #e9c2d044 !important;
  outline: none !important;
}

input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--dusty) !important;
}

/* ===== FOOTER ===== */

footer,
.footer {
  background: var(--dusty) !important;
  color: white !important;
  border-color: var(--dusty) !important;
}

footer a,
.footer a {
  color: white !important;
}

/* ===== TABLES ===== */

table {
  background: var(--white) !important;
  border-radius: 12px !important;
  overflow: hidden;
}

tr:hover td {
  background: var(--blush) !important;
}

/* ===== ALERTS ===== */

.alert,
.alert-info,
.alert-success,
.alert-warning,
.alert-danger {
  background: var(--blush) !important;
  color: var(--deep) !important;
  border: 1px solid var(--border) !important;
  border-radius: 12px !important;
}

/* ===== LABELS ===== */

.label,
.badge {
  background: var(--pink) !important;
  color: var(--deep) !important;
  border-radius: 20px !important;
}

/* ===== MODALS ===== */

.modal-content {
  background: var(--white) !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
  border-radius: 16px !important;
}

.modal-header {
  background: var(--blush) !important;
  border-color: var(--border) !important;
}

/* ===== SCROLLBAR ===== */

::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

::-webkit-scrollbar-track {
  background: var(--bg);
}

::-webkit-scrollbar-thumb {
  background: var(--pink);
  border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--dusty);
}

/* ===== TEXT SELECTION ===== */

::selection {
  background: var(--pink);
  color: var(--deep);
}
}
